body,
#root {
    height: 100%;
    margin: 0;
}

* {
    box-sizing: border-box;
}

body {
    background: #1e1f22;
    color: #f2f3f5;
    font-family: Arial, sans-serif;
    overflow: hidden;
}

button,
input,
textarea,
select {
    font: inherit;
}

button {
    border: 0;
}

.discord-shell {
    background: #313338;
    color: #f2f3f5;
    display: grid;
    grid-template-columns: 72px 260px minmax(0, 1fr) 240px;
    height: 100vh;
    min-height: 0;
    padding: 0;
}

.server-rail {
    align-items: center;
    background: #1e1f22;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 12px 0;
}

.server-bubble {
    align-items: center;
    background: #313338;
    border-radius: 50%;
    color: #dbdee1;
    cursor: pointer;
    display: flex;
    font-size: 14px;
    font-weight: 800;
    height: 48px;
    justify-content: center;
    transition: background-color 0.15s ease, border-radius 0.15s ease, color 0.15s ease;
    width: 48px;
}

.server-bubble:hover,
.server-bubble.active {
    background: #5865f2;
    border-radius: 16px;
    color: #fff;
}

.server-bubble.home {
    background: #23a559;
    color: #fff;
}

.server-bubble.dm-bubble {
    margin-top: auto;
}

.server-divider {
    background: #35363c;
    border-radius: 999px;
    height: 2px;
    width: 32px;
}

.sidebar-panel {
    background: #2b2d31;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.sidebar-title {
    align-items: center;
    border-bottom: 1px solid #1f2023;
    display: flex;
    font-weight: 800;
    height: 52px;
    justify-content: space-between;
    padding: 0 14px;
}

.theme-toggle {
    background: #383a40;
    border-radius: 6px;
    color: #dbdee1;
    cursor: pointer;
    font-size: 12px;
    height: 30px;
    padding: 0 10px;
}

.theme-toggle:hover {
    background: #4752c4;
    color: #fff;
}

.sidebar-section-label {
    color: #949ba4;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.04em;
    padding: 18px 14px 8px;
    text-transform: uppercase;
}

.connection-pill {
    border-radius: 6px;
    font-size: 12px;
    font-weight: 800;
    margin: 10px 10px 0;
    padding: 8px 10px;
    text-transform: capitalize;
}

.connection-pill.connected {
    background: rgba(35, 165, 89, 0.16);
    color: #5be285;
}

.connection-pill.offline {
    background: rgba(242, 63, 67, 0.16);
    color: #ff7b7e;
}

.channel-list {
    display: flex;
    flex: 1;
    flex-direction: column;
    gap: 2px;
    min-height: 0;
    overflow-y: auto;
    padding: 0 8px;
}

.channel-row,
.dm-row,
.member-row {
    align-items: center;
    background: transparent;
    border-radius: 6px;
    color: #949ba4;
    cursor: pointer;
    display: flex;
    gap: 10px;
    min-height: 36px;
    padding: 0 10px;
    text-align: left;
    width: 100%;
}

.channel-row span {
    color: #80848e;
    font-size: 20px;
}

.channel-row:hover,
.dm-row:hover,
.member-row:hover,
.channel-row.active,
.dm-row.active {
    background: #3a3c43;
    color: #f2f3f5;
}

.mini-avatar {
    align-items: center;
    background: #5865f2;
    border-radius: 50%;
    color: #fff;
    display: inline-flex;
    flex: 0 0 auto;
    font-size: 12px;
    font-weight: 800;
    height: 28px;
    justify-content: center;
    width: 28px;
}

.mini-avatar.self {
    background: #23a559;
}

.account-card {
    align-items: center;
    background: #232428;
    display: flex;
    gap: 10px;
    margin-top: auto;
    min-height: 58px;
    padding: 10px;
}

.account-name {
    font-size: 14px;
    font-weight: 800;
}

.account-status {
    color: #949ba4;
    font-size: 12px;
}

.chat-main {
    background: #313338;
    display: flex;
    flex-direction: column;
    min-height: 0;
    min-width: 0;
}

.chat-topbar {
    align-items: center;
    border-bottom: 1px solid #26282d;
    display: flex;
    gap: 20px;
    min-height: 52px;
    padding: 0 18px;
}

.chat-topbar h1 {
    color: #f2f3f5;
    font-size: 18px;
    line-height: 1;
    margin: 0;
}

.chat-topbar p {
    color: #949ba4;
    font-size: 12px;
    margin: 4px 0 0;
}

.search-container {
    margin-left: auto;
    max-width: 280px;
    width: 35%;
}

.search-input {
    background: #1e1f22;
    border: 1px solid #25262b;
    border-radius: 6px;
    color: #dbdee1;
    height: 34px;
    outline: none;
    padding: 0 12px;
    width: 100%;
}

.search-input:focus {
    border-color: #5865f2;
}

.encryption-strip {
    align-items: center;
    display: flex;
    gap: 10px;
    padding: 12px 18px 0;
}

.encryption-strip input {
    background: #1e1f22;
    border: 1px solid #25262b;
    border-radius: 6px;
    color: #dbdee1;
    height: 34px;
    max-width: 340px;
    outline: none;
    padding: 0 12px;
    width: 100%;
}

.encryption-strip span {
    color: #23a559;
    font-size: 13px;
    font-weight: 800;
}

.messages-container {
    background: #313338;
    border: 0;
    flex: 1;
    min-height: 0;
    overflow-y: auto;
    padding: 18px;
}

.message {
    border-radius: 8px;
    margin-bottom: 8px;
    padding: 10px 12px;
    word-break: break-word;
}

.message:hover {
    background: #2e3035;
}

.message.own {
    background: rgba(88, 101, 242, 0.12);
}

.message.notification {
    color: #f0b232;
    font-style: italic;
    text-align: center;
}

.message.private {
    background: rgba(235, 69, 158, 0.12);
}

.username {
    color: #f2f3f5;
    font-weight: 800;
    margin-right: 8px;
}

.message-text {
    color: #dbdee1;
    line-height: 1.45;
}

.message-text code {
    background: #1e1f22;
    border-radius: 4px;
    padding: 2px 5px;
}

.timestamp {
    color: #949ba4;
    font-size: 12px;
    margin-left: 8px;
}

.private-msg {
    background: #eb459e;
    border-radius: 4px;
    color: #fff;
    font-size: 11px;
    font-weight: 800;
    margin-left: 8px;
    padding: 2px 6px;
}

.file-message {
    background: #2b2d31;
    border: 1px solid #3f424a;
}

.file-header {
    align-items: baseline;
    display: flex;
    justify-content: space-between;
    margin-bottom: 8px;
}

.file-preview {
    margin: 10px 0;
}

.file-preview img {
    border-radius: 8px;
    display: block;
    max-height: 260px;
    max-width: min(100%, 380px);
    object-fit: contain;
}

.file-link {
    color: #7dd3fc;
    font-weight: 800;
    text-decoration: none;
}

.encrypted-label {
    background: rgba(35, 165, 89, 0.16);
    border-radius: 999px;
    color: #5be285;
    display: inline-flex;
    font-size: 11px;
    font-weight: 800;
    margin: 0 0 8px;
    padding: 3px 8px;
}

.encrypted-label.inline {
    margin: 0 8px 0 0;
    vertical-align: middle;
}

.file-decrypt-button {
    background: #5865f2;
    border-radius: 8px;
    color: #fff;
    cursor: pointer;
    font-weight: 800;
    min-height: 40px;
    padding: 0 12px;
    text-align: left;
}

.file-decrypt-button:hover {
    background: #4752c4;
}

.file-link:hover {
    text-decoration: underline;
}

.reactions {
    display: none;
}

.typing-indicator,
.empty-compose {
    color: #949ba4;
    font-size: 13px;
    padding: 0 18px 10px;
}

.message-input-container {
    background: #313338;
    display: flex;
    flex-direction: column;
    gap: 10px;
    padding: 0 18px 18px;
}

.username-input {
    background: #1e1f22;
    border: 1px solid #25262b;
    border-radius: 6px;
    color: #dbdee1;
    height: 34px;
    outline: none;
    padding: 0 12px;
    width: 220px;
}

.composer-row {
    align-items: flex-end;
    display: flex;
    gap: 10px;
}

.message-textarea.composer-box {
    align-items: flex-end;
    background: #383a40;
    border: 1px solid transparent;
    border-radius: 8px;
    color: #dbdee1;
    display: flex;
    flex: 1;
    min-height: 46px;
    padding: 9px 12px;
}

.message-textarea.composer-box:focus-within {
    border-color: #5865f2;
}

.composer-textarea {
    background: transparent;
    border: 0;
    color: inherit;
    flex: 1;
    line-height: 24px;
    margin: 0;
    max-height: 120px;
    min-height: 24px;
    outline: none;
    overflow-y: auto;
    padding: 0;
    resize: none;
}

.upload-button {
    align-items: center;
    background: #4e5058;
    border-radius: 50%;
    color: #f2f3f5;
    cursor: pointer;
    display: inline-flex;
    flex: 0 0 auto;
    font-size: 14px;
    font-weight: 900;
    height: 28px;
    justify-content: center;
    margin-right: 10px;
    width: 28px;
}

.upload-button:hover {
    background: #5865f2;
}

.upload-button:disabled {
    cursor: wait;
    opacity: 0.65;
}

.send-button {
    background: #5865f2;
    border-radius: 8px;
    color: #fff;
    cursor: pointer;
    flex: 0 0 auto;
    font-weight: 800;
    height: 46px;
    padding: 0 18px;
}

.send-button:hover {
    background: #4752c4;
}

.send-button:disabled {
    cursor: not-allowed;
    opacity: 0.5;
}

.upload-status {
    color: #949ba4;
    font-size: 13px;
    min-height: 18px;
}

.upload-status.active {
    color: #7dd3fc;
}

.members-panel {
    background: #2b2d31;
    display: flex;
    flex-direction: column;
    min-height: 0;
}

.members-title {
    color: #949ba4;
    font-size: 12px;
    font-weight: 800;
    letter-spacing: 0.04em;
    padding: 18px 14px 8px;
    text-transform: uppercase;
}

.members-list {
    display: flex;
    flex-direction: column;
    gap: 2px;
    min-height: 0;
    overflow-y: auto;
    padding: 0 8px;
}

.member-row small {
    color: #949ba4;
    margin-left: auto;
}

.empty-state {
    color: #949ba4;
    font-size: 13px;
    padding: 10px;
}

.app.light {
    color: #2e3338;
}

.app.light.discord-shell {
    background: #fff;
}

.app.light .chat-main,
.app.light .messages-container,
.app.light .message-input-container {
    background: #fff;
}

.app.light .sidebar-panel,
.app.light .members-panel {
    background: #f2f3f5;
}

.app.light .server-rail {
    background: #e3e5e8;
}

.app.light .message-text,
.app.light .chat-topbar h1,
.app.light .username {
    color: #2e3338;
}

.app.light .chat-topbar p,
.app.light .sidebar-section-label,
.app.light .members-title,
.app.light .timestamp,
.app.light .empty-state {
    color: #5c6570;
}

.app.light .search-input,
.app.light .encryption-strip input,
.app.light .username-input {
    background: #fff;
    border-color: #d6d9df;
    color: #2e3338;
}

.app.light .message-textarea.composer-box {
    background: #ebedef;
    color: #2e3338;
}

@media (max-width: 1100px) {
    .discord-shell {
        grid-template-columns: 72px 230px minmax(0, 1fr);
    }

    .members-panel {
        display: none;
    }
}

@media (max-width: 760px) {
    body {
        overflow: auto;
    }

    .discord-shell {
        grid-template-columns: 56px minmax(104px, 32vw) minmax(0, 1fr);
        height: 100vh;
    }

    .server-rail {
        grid-row: auto;
        padding: 8px 0;
    }

    .server-bubble {
        height: 42px;
        width: 42px;
    }

    .sidebar-panel {
        display: flex;
        min-width: 104px;
    }

    .sidebar-title {
        align-items: flex-start;
        flex-direction: column;
        gap: 6px;
        height: auto;
        min-height: 68px;
        padding: 10px;
    }

    .theme-toggle {
        width: 100%;
    }

    .connection-pill {
        font-size: 11px;
        margin: 8px 8px 0;
        padding: 6px 8px;
    }

    .sidebar-section-label {
        font-size: 10px;
        padding: 12px 8px 6px;
    }

    .channel-list {
        padding: 0 6px;
    }

    .channel-row,
    .dm-row {
        gap: 5px;
        min-height: 34px;
        padding: 0 6px;
    }

    .account-card {
        align-items: flex-start;
        flex-direction: column;
        padding: 8px;
    }

    .chat-topbar {
        align-items: flex-start;
        flex-direction: column;
        gap: 10px;
        padding: 12px;
    }

    .search-container {
        margin-left: 0;
        max-width: none;
        width: 100%;
    }

    .encryption-strip,
    .messages-container,
    .message-input-container {
        padding-left: 12px;
        padding-right: 12px;
    }

    .composer-row {
        align-items: stretch;
        flex-direction: column;
    }

    .send-button {
        width: 100%;
    }

    .username-input {
        width: 100%;
    }
